parameters.functionCode:
// Input:  $json.startIso, $json.endIso  (on the SAME item)
// Output: dayStartIso, dayEndIso, requestWindow

if (!$json.startIso || !$json.endIso) {
  return [{ json: { error: 'Missing startIso/endIso on current item' } }];
}

const start = new Date($json.startIso);
const end   = new Date($json.endIso);

// derive "local" day boundaries from start's timezone offset
const tzOffsetMin = start.getTimezoneOffset(); // minutes offset from UTC (note: sign is opposite)
function startOfDay(dt) {
  const d = new Date(dt);
  d.setHours(0, 0, 0, 0);
  return d;
}
function endOfDay(dt) {
  const d = new Date(dt);
  d.setHours(23, 59, 59, 999);
  return d;
}

const dayStart = startOfDay(start);
const dayEnd   = endOfDay(start);

// Keep them as ISO-8601 strings
return [{
  json: {
    requestWindow: { startIso: $json.startIso, endIso: $json.endIso },
    dayStartIso: dayStart.toISOString(),
    dayEndIso: dayEnd.toISOString()
  }
}];

// Works with Google FreeBusy response:
// { calendars: { "<calendarId>": { busy: [{start, end}, ...] } }, ... }

const calendars = $json.calendars || {};

// Prefer a calendarId from the item if you passed one earlier; else take the first key; else 'primary'
const calendarId =
  $json.calendarId ||
  Object.keys(calendars)[0] ||
  'primary';

const busyArr = Array.isArray(calendars[calendarId]?.busy)
  ? calendars[calendarId].busy
  : [];

// Pretty print in Asia/Dubai
const fmt = new Intl.DateTimeFormat('en-GB', {
  dateStyle: 'medium',
  timeStyle: 'short',
  timeZone: 'Asia/Dubai',
});

const busySlotsUAE = busyArr.map(b => ({
  startIso: b.start,
  endIso: b.end,
  start: fmt.format(new Date(b.start)),
  end: fmt.format(new Date(b.end)),
}));

return [{
  json: {
    calendarId,
    busySlotsCount: busySlotsUAE.length,
    busySlotsUAE,
    window: { timeMin: $json.timeMin, timeMax: $json.timeMax }
  }
}];

/**
 * Pass-through + Dubai ISO window from natural phrases like "tomorrow 5pm"
 * Output fields:
 *  - startIso (e.g., 2025-09-25T17:00:00+04:00)
 *  - endIso   (start + 30min)
 *  - timeZone ("Asia/Dubai")
 *  - rawTime  (original)
 *  - ...all original input fields
 */

const TZ = 'Asia/Dubai';

function pickRawTime(obj) {
  if (!obj) return '';
  if (typeof obj === 'string') return obj;
  return (
    obj.time ||
    obj.appTime ||
    obj?.message?.content ||
    obj.content ||
    obj.text ||
    obj.data ||
    ''
  );
}

function parseNaturalToDubaiISO(nl) {
  const s = String(nl || '').trim();
  if (!s) throw new Error('No time provided');

  // If it already looks ISO-ish (YYYY-MM-DD...), let Luxon parse then move to Dubai
  if (/^\d{4}-\d{2}-\d{2}T?\d{0,2}:?\d{0,2}:?\d{0,2}(\.\d+)?([+-]\d{2}:\d{2}|Z)?$/i.test(s)) {
    const dt = DateTime.fromISO(s, { setZone: true });
    if (!dt.isValid) throw new Error('Invalid ISO datetime: ' + s);
    return dt.setZone(TZ).toISO({ includeOffset: true, suppressMilliseconds: true });
  }

  // Otherwise treat it as a natural phrase like "today 3pm", "tomorrow 5pm"
  let base = DateTime.now().setZone(TZ);

  const low = s.toLowerCase();

  // Day words
  if (low.includes('tomorrow')) base = base.plus({ days: 1 });
  else if (low.includes('today')) base = base.plus({ days: 0 });

  // Optional weekday (next monday 2pm)
  const wk = low.match(/\bnext\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/);
  if (wk) {
    const names = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
    const target = names.indexOf(wk[1]);
    let diff = (target - base.weekday % 7 + 7) % 7;
    if (diff === 0) diff = 7; // always next, not today
    base = base.plus({ days: diff });
  }

  // Time: "5pm", "5 pm", "17:30", "5:15 pm"
  const m = low.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i);
  if (!m) throw new Error('Could not find a time like 5pm or 17:30 in: ' + s);

  let hour = parseInt(m[1], 10);
  let minute = parseInt(m[2] || '0', 10);
  const ap = (m[3] || '').toLowerCase();
  if (ap === 'pm' && hour < 12) hour += 12;
  if (ap === 'am' && hour === 12) hour = 0;

  const dt = base.set({ hour, minute, second: 0, millisecond: 0 });
  return dt.toISO({ includeOffset: true, suppressMilliseconds: true });
}

// ---- main ----
const input = { ...$json };
const raw = String(pickRawTime(input) || '').trim();
if (!raw) throw new Error('No time provided');

const startIso = parseNaturalToDubaiISO(raw);
const endIso = DateTime.fromISO(startIso, { setZone: true })
  .plus({ minutes: 30 })
  .toISO({ includeOffset: true, suppressMilliseconds: true });

return [
  {
    json: {
      ...input,
      rawTime: raw,
      startIso,
      endIso,
      timeZone: TZ,
    },
  },
];

